{"code": "import math

def count_divisors(n):
    count = 1
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            exp = 0
            while n % i == 0:
                n //= i
                exp += 1
            count *= (exp + 1)
    if n > 1:
        count *= 2
    return count

result = count_divisors(2002)
print(result)
"}

