# CAPABILITY_CHECK: Verify maximum value of c * a**b - d with a,b,c,d being a permutation of {0,1,2,3}
max_value = -float('inf')
values = [0, 1, 2, 3]

# Iterate over all possible assignments of a, b, c, d
for a in values:
    for b in values:
        # 0**0 is mathematically undefined, so skip this case
        if a == 0 and b == 0:
            continue
        for c in values:
            for d in values:
                # Ensure each number is used exactly once
                if len({a, b, c, d}) == 4:
                    result = c * (a ** b) - d
                    if result > max_value:
                        max_value = result

print(max_value)
"}

